-- Align the practice sidebar (vocabulary_items) to the TRAINING vocab
-- (dataset/sem_lex_top80_vocabulary.json — the 80 top-sem_lex words).
--
-- WHY .draft / NOT auto-applied: 55 of these 80 signs are NEW to the DB
-- (old table = slice1b: again/mom/dad/know/...). Activating them WITHOUT
-- reference videos + avatar templates would surface words whose practice
-- screen is broken. Apply ONLY after those assets exist:
--   * avatar templates  -> public/templates/<sign>.json  (DONE: medoid export)
--   * reference videos   -> 20260524010000_seed_reference_videos_top80.sql
-- Recognition is unaffected: all model_versions rows are deactivated
-- (20260520200000), so the runner uses stubPredict() for every sign.
-- Sidebar order = sem_lex clip count desc (most-trained first). Categories
-- are semantic (see prettyCategory / CATEGORY_LABELS in sidebar.tsx).
--
-- Apply: mv ...sql.draft ...sql && supabase db push  (or run in SQL editor)

-- 1) deactivate everything, then (2) upsert+activate the 80 training signs.
update public.vocabulary_items set is_active_for_practice = false;



-- 3) The 10 signs without a mocap avatar yet → "Pending" category. The sidebar
-- (components/practice/sidebar.tsx) renders the "pending" category LAST and
-- labels it "Pending — avatar coming soon". They stay active for practice
-- (recognition is stubPredict) but visually flag that the avatar is in progress.
update public.vocabulary_items set category = 'pending'
where id in ('eat','time','numbers','sports','cool','dark','sick','baby','follow','nothing');
